import React from 'react';
import { toast } from 'react-toastify';
import { Form, Input, Button, Space } from 'antd';
import { MinusCircleOutlined, PlusOutlined } from '@ant-design/icons';
import { updateWhatIsGymkhana, createWhatIsGymkhana } from '../../services/api';

const { TextArea } = Input;

const WhatIsGymkhanaForm = ({ initialValues, onSuccess }) => {
  const [form] = Form.useForm();
  const isEditing = Boolean(initialValues?.id);

  React.useEffect(() => {
    form.resetFields();
    if (initialValues) {
      const formattedValues = {
        ...initialValues,
        competitionFormats: initialValues.competitionFormats ? JSON.parse(initialValues.competitionFormats) : [],
        technicalElements: initialValues.technicalElements ? JSON.parse(initialValues.technicalElements) : [],
        scoringElements: initialValues.scoringElements ? JSON.parse(initialValues.scoringElements) : []
      };
      form.setFieldsValue(formattedValues);
    }
  }, [initialValues, form]);

  const onFinish = async (values) => {
    try {
      const dataToSubmit = {
        ...values,
        competitionFormats: JSON.stringify(values.competitionFormats),
        technicalElements: JSON.stringify(values.technicalElements),
        scoringElements: JSON.stringify(values.scoringElements)
      };

      if (isEditing) {
        await updateWhatIsGymkhana(initialValues.id, dataToSubmit);
      } else {
        await createWhatIsGymkhana(dataToSubmit);
      }
      onSuccess();
    } catch (error) {
      toast.error(`Failed to ${isEditing ? 'update' : 'create'} content`);
    }
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          initialValues={{
            competitionFormats: [],
            technicalElements: [],
            scoringElements: []
          }}
        >
          <Form.Item
            name="title"
            label="Title"
            rules={[{ required: true, message: 'Please enter title' }]}
          >
            <Input placeholder="Enter title" />
          </Form.Item>

          <Form.Item
            name="subtitle"
            label="Subtitle"
            rules={[{ required: true, message: 'Please enter subtitle' }]}
          >
            <TextArea
              rows={4}
              placeholder="Enter subtitle"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item
            name="description"
            label="Description"
            rules={[{ required: true, message: 'Please enter description' }]}
          >
            <TextArea
              rows={6}
              placeholder="Enter description"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.List name="competitionFormats">
            {(fields, { add, remove }) => (
              <>
                <Form.Item label="Competition Formats">
                  {fields.map((field, index) => (
                    <Space key={field.key} style={{ display: 'flex', marginBottom: 8 }} align="baseline">
                      <Form.Item
                        {...field}
                        rules={[{ required: true, message: 'Please enter format' }]}
                      >
                        <Input placeholder="Enter competition format" />
                      </Form.Item>
                      <MinusCircleOutlined onClick={() => remove(field.name)} />
                    </Space>
                  ))}
                </Form.Item>
                <Form.Item>
                  <Button
                    type="dashed"
                    onClick={() => add()}
                    block
                    icon={<PlusOutlined />}
                  >
                    Add Competition Format
                  </Button>
                </Form.Item>
              </>
            )}
          </Form.List>

          <Form.List name="technicalElements">
            {(fields, { add, remove }) => (
              <>
                <Form.Item label="Technical Elements">
                  {fields.map((field, index) => (
                    <Space key={field.key} style={{ display: 'flex', marginBottom: 8 }} align="baseline">
                      <Form.Item
                        {...field}
                        rules={[{ required: true, message: 'Please enter element' }]}
                      >
                        <Input placeholder="Enter technical element" />
                      </Form.Item>
                      <MinusCircleOutlined onClick={() => remove(field.name)} />
                    </Space>
                  ))}
                </Form.Item>
                <Form.Item>
                  <Button
                    type="dashed"
                    onClick={() => add()}
                    block
                    icon={<PlusOutlined />}
                  >
                    Add Technical Element
                  </Button>
                </Form.Item>
              </>
            )}
          </Form.List>

          <Form.List name="scoringElements">
            {(fields, { add, remove }) => (
              <>
                <Form.Item label="Scoring Elements">
                  {fields.map((field, index) => (
                    <Space key={field.key} style={{ display: 'flex', marginBottom: 8 }} align="baseline">
                      <Form.Item
                        {...field}
                        rules={[{ required: true, message: 'Please enter element' }]}
                      >
                        <Input placeholder="Enter scoring element" />
                      </Form.Item>
                      <MinusCircleOutlined onClick={() => remove(field.name)} />
                    </Space>
                  ))}
                </Form.Item>
                <Form.Item>
                  <Button
                    type="dashed"
                    onClick={() => add()}
                    block
                    icon={<PlusOutlined />}
                  >
                    Add Scoring Element
                  </Button>
                </Form.Item>
              </>
            )}
          </Form.List>

          <Form.Item>
            <Button type="primary" htmlType="submit">
              {isEditing ? 'Update' : 'Create'}
            </Button>
          </Form.Item>
        </Form>
      </Space>
    </div>
  );
};

export default WhatIsGymkhanaForm;
