import { Card } from 'antd';
import { toast } from 'react-toastify';
import { useState, useEffect } from 'react';
import { getAboutContent } from '../services/api';
import AboutForm from '../components/about/AboutForm';

const AboutPage = () => {
  const [content, setContent] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchAboutContent = async () => {
    setLoading(true);
    try {
      const data = await getAboutContent();
      if (!data) {
        setContent(null);
        return;
      }
      const processData = (item) => {
        if (item && typeof item.characteristics === 'string') {
          try {
            item.characteristics = JSON.parse(item.characteristics);
          } catch (e) {
            console.error('Error parsing characteristics:', e);
            item.characteristics = [];
          }
        }
        return item;
      };

      if (!Array.isArray(data)) {
        setContent(processData(data));
        return;
      }
      setContent(data.length > 0 ? processData(data[0]) : null);
    } catch (error) {
      toast.error(`Failed to fetch about content: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleSuccess = () => { fetchAboutContent() };

  useEffect(() => { fetchAboutContent() }, []);

  return (
    <Card
      title="About Content"
      loading={loading}
    >
      <AboutForm
        initialValues={content}
        onSuccess={handleSuccess}
      />
    </Card>
  );
};

export default AboutPage;
