import React from 'react';
import { toast } from 'react-toastify';
import { Form, Input, Button, Space } from 'antd';
import { updateContact, createContact } from '../../services/api';

const { TextArea } = Input;

const ContactForm = ({ initialValues, onSuccess }) => {
  const [form] = Form.useForm();
  const isEditing = Boolean(initialValues?.id);

  React.useEffect(() => {
    form.resetFields();
    if (initialValues) {
      const formattedValues = {
        ...initialValues,
        socialMedia: initialValues.socialMedia ? JSON.parse(initialValues.socialMedia) : {}
      };
      form.setFieldsValue(formattedValues);
    }
  }, [initialValues, form]);

  const onFinish = async (values) => {
    try {
      const dataToSubmit = {
        ...values,
        socialMedia: JSON.stringify(values.socialMedia || {})
      };

      if (isEditing) {
        await updateContact(initialValues.id, dataToSubmit);
        toast.success('Contact updated successfully');
      } else {
        await createContact(dataToSubmit);
        toast.success('Contact created successfully');
      }
      onSuccess();
    } catch (error) {
      toast.error(`Failed to ${isEditing ? 'update' : 'create'} contact`);
    }
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        <Form
          form={form}
          layout="vertical"
          onFinish={onFinish}
          initialValues={{
            email: '',
            phone: '',
            address: '',
            socialMedia: {},
            mapUrl: '',
          }}
        >
          <Form.Item
            name="email"
            label="Email"
            rules={[
              { required: true, message: 'Please enter email' },
              { type: 'email', message: 'Please enter a valid email' }
            ]}
          >
            <Input placeholder="Enter email" />
          </Form.Item>

          <Form.Item
            name="phone"
            label="Phone"
            rules={[{ required: true, message: 'Please enter phone number' }]}
          >
            <Input placeholder="Enter phone number" />
          </Form.Item>

          <Form.Item
            name="address"
            label="Address"
            rules={[{ required: true, message: 'Please enter address' }]}
          >
            <TextArea
              rows={4}
              placeholder="Enter address"
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'facebook']}
            label="Facebook URL"
          >
            <Input placeholder="Enter Facebook URL" />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'twitter']}
            label="Twitter URL"
          >
            <Input placeholder="Enter Twitter URL" />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'instagram']}
            label="Instagram URL"
          >
            <Input placeholder="Enter Instagram URL" />
          </Form.Item>

          <Form.Item
            name={['socialMedia', 'youtube']}
            label="YouTube URL"
          >
            <Input placeholder="Enter YouTube URL" />
          </Form.Item>

          <Form.Item
            name="mapUrl"
            label="Map Embed"
            tooltip="Paste the full Google Maps iframe embed snippet."
            rules={[
              {
                validator: (_, value) => {
                  if (!value) return Promise.resolve();
                  const v = String(value).trim();
                  return /<iframe[\s\S]*src=["']https?:\/\/(?:www\.)?google\.com\/maps[^"']*["'][\s\S]*><\/iframe>/i.test(v)
                    ? Promise.resolve()
                    : Promise.reject(new Error('Please provide a Google Maps <iframe> embed code.'));
                },
              },
            ]}
          >
            <TextArea
              rows={4}
              placeholder='<iframe src="https://www.google.com/maps/embed?..." width="600" height="450" style="border:0;" allowFullScreen="" loading="lazy"></iframe>'
              style={{ resize: 'vertical' }}
            />
          </Form.Item>

          <Form.Item>
            <Button type="primary" htmlType="submit">
              {isEditing ? 'Update Contact' : 'Create Contact'}
            </Button>
          </Form.Item>
        </Form>
      </Space>
    </div>
  );
}
  ;

export default ContactForm;
