import {
  Card,
  Table,
  Tag,
  Space,
  Button,
  Modal,
  Typography,
  Badge,
} from 'antd';
import { toast } from 'react-toastify';
import { useState, useEffect } from 'react';
import { getAllMessages, updateMessageStatus, deleteMessage } from '../services/api';

const { Text } = Typography;

const MessagesPage = () => {
  const [messages, setMessages] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedMessage, setSelectedMessage] = useState(null);
  const [modalVisible, setModalVisible] = useState(false);

  const fetchMessages = async () => {
    try {
      const data = await getAllMessages();
      setMessages(data);
    } catch (error) {
      toast.error('Failed to fetch messages');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMessages();
  }, []);

  const handleViewMessage = (message) => {
    setSelectedMessage(message);
    setModalVisible(true);
    if (message.status === 'new') {
      handleUpdateStatus(message.id, 'read');
    }
  };

  const handleUpdateStatus = async (id, status) => {
    try {
      await updateMessageStatus(id, { status });
      fetchMessages();
      toast.success('Status updated successfully');
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const handleDeleteMessage = async (id) => {
    try {
      await deleteMessage(id);
      fetchMessages();
      toast.success('Message deleted successfully');
    } catch (error) {
      toast.error('Failed to delete message');
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'new':
        return 'blue';
      case 'read':
        return 'green';
      case 'replied':
        return 'purple';
      default:
        return 'default';
    }
  };

  const columns = [
    {
      title: 'Name',
      dataIndex: 'name',
      key: 'name',
      render: (text, record) => (
        <Space>
          {text}
          {record.status === 'new' && <Badge status="processing" />}
        </Space>
      ),
    },
    {
      title: 'Email',
      dataIndex: 'email',
      key: 'email',
    },
    {
      title: 'Subject',
      dataIndex: 'subject',
      key: 'subject',
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      render: (status) => (
        <Tag color={getStatusColor(status)}>
          {status.charAt(0).toUpperCase() + status.slice(1)}
        </Tag>
      ),
    },
    {
      title: 'Date',
      dataIndex: 'createdAt',
      key: 'createdAt',
      render: (date) => new Date(date).toLocaleDateString(),
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space>
          <Button type="primary" onClick={() => handleViewMessage(record)}>
            View
          </Button>
          <Button
            type="default"
            onClick={() => handleUpdateStatus(record.id, 'replied')}
            disabled={record.status === 'replied'}
          >
            Mark Replied
          </Button>
          <Button danger onClick={() => handleDeleteMessage(record.id)}>
            Delete
          </Button>
        </Space>
      ),
    },
  ];

  return (
    <>
      <Card title="Messages">
        <Table
          columns={columns}
          dataSource={messages}
          rowKey="id"
          loading={loading}
        />
      </Card>

      <Modal
        title={`Message from ${selectedMessage?.name}`}
        open={modalVisible}
        onCancel={() => setModalVisible(false)}
        footer={[
          <Button key="close" onClick={() => setModalVisible(false)}>
            Close
          </Button>,
        ]}
        width={600}
      >
        {selectedMessage && (
          <Space direction="vertical" size="large" style={{ width: '100%' }}>
            <div>
              <Text strong>From: </Text>
              <Text>{selectedMessage.name}</Text>
            </div>
            <div>
              <Text strong>Email: </Text>
              <Text>{selectedMessage.email}</Text>
            </div>
            <div>
              <Text strong>Phone: </Text>
              <Text>{selectedMessage.phone}</Text>
            </div>
            <div>
              <Text strong>Subject: </Text>
              <Text>{selectedMessage.subject}</Text>
            </div>
            <div>
              <Text strong>Message: </Text>
              <Text>{selectedMessage.message}</Text>
            </div>
            <div>
              <Text strong>Status: </Text>
              <Tag color={getStatusColor(selectedMessage.status)}>
                {selectedMessage.status.charAt(0).toUpperCase() +
                  selectedMessage.status.slice(1)}
              </Tag>
            </div>
            <div>
              <Text strong>Received: </Text>
              <Text>
                {new Date(selectedMessage.createdAt).toLocaleString()}
              </Text>
            </div>
          </Space>
        )}
      </Modal>
    </>
  );
};

export default MessagesPage;
