import { toast } from 'react-toastify';
import { Table, Button, Space, Image } from 'antd';
import { EditOutlined, DeleteOutlined } from '@ant-design/icons';
import { useState, useEffect, forwardRef, useImperativeHandle } from 'react';
import { getGalleryItems, deleteGalleryItem } from '../../services/galleryApi';

const GalleryList = forwardRef(function GalleryList({ onEdit }, ref) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(false);

  const fetchGalleryItems = async () => {
    setLoading(true);
    try {
      const data = await getGalleryItems();
      setItems(data);
    } catch (error) {
      toast.error('Failed to fetch gallery items');
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchGalleryItems();
  }, []);

  useImperativeHandle(ref, () => ({
    refresh: fetchGalleryItems
  }));

  const handleDelete = async (id) => {
    try {
      await deleteGalleryItem(id);
      toast.success('Gallery item deleted successfully');
      fetchGalleryItems();
    } catch (error) {
      toast.error('Failed to delete gallery item');
    }
  };

  const columns = [
    {
      title: 'Cover Image',
      dataIndex: 'imageUrl',
      key: 'imageUrl',
      render: (imageUrl, record) => {
        return record?.coverImage && (
          <Image.PreviewGroup items={[record.coverImage]}>
            <Image
              alt="webp image"
              width={100}
              height={100}
              src={record.coverImage}
            />
          </Image.PreviewGroup>
        );
      },
    },
    {
      title: 'Title',
      dataIndex: 'title',
      key: 'title',
    },
    {
      title: 'Folder',
      dataIndex: 'folderName',
      key: 'folderName',
    },
    {
      title: 'Actions',
      key: 'actions',
      render: (_, record) => (
        <Space>
          <Button
            type="primary"
            icon={<EditOutlined />}
            onClick={() => onEdit(record)}
          >
            Edit
          </Button>
          <Button
            type="primary"
            danger
            icon={<DeleteOutlined />}
            onClick={() => handleDelete(record.id)}
          >
            Delete
          </Button>
        </Space>
      ),
    },
  ];

  return (
    <Table
      columns={columns}
      dataSource={items}
      rowKey="id"
      loading={loading}
    />
  );
});

export default GalleryList;
