import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  IconButton,
} from '@mui/material';
import { toast } from 'react-toastify';
import HistoryForm from './HistoryForm';
import { useState, useEffect } from 'react';
import { getHistoryItems, deleteHistoryItem } from '../../services/api';
import { Edit as EditIcon, Delete as DeleteIcon, Add as AddIcon } from '@mui/icons-material';

const HistoryList = () => {
  const [items, setItems] = useState([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);

  const fetchItems = async () => {
    try {
      const data = await getHistoryItems();
      setItems(data);
    } catch (error) {
      toast.error('Failed to fetch history items');
    }
  };

  useEffect(() => {
    fetchItems();
  }, []);

  const handleEdit = (item) => {
    setSelectedItem(item);
    setDialogOpen(true);
  };

  const handleDelete = async (id) => {
    try {
      await deleteHistoryItem(id);
      toast.success('History item deleted successfully');
      fetchItems();
    } catch (error) {
      toast.error('Failed to delete history item');
    }
  };

  const handleDialogClose = () => {
    setDialogOpen(false);
    setSelectedItem(null);
  };

  const handleFormSuccess = () => {
    handleDialogClose();
    fetchItems();
  };

  const columns = [
    { id: 'title', label: 'Title' },
    { id: 'year', label: 'Year' },
    { id: 'order', label: 'Order' },
    {
      id: 'imageUrl',
      label: 'Image',
      render: (imageUrl) => imageUrl ? (
        <img
          src={imageUrl.startsWith('http') ? imageUrl : `${process.env.REACT_APP_API_URL}${imageUrl}`}
          alt="History"
          style={{ maxWidth: '100px', maxHeight: '60px' }}
        />
      ) : 'No image'
    },
    {
      id: 'actions',
      label: 'Actions',
      render: (_, item) => (
        <>
          <IconButton color="primary" onClick={() => handleEdit(item)}>
            <EditIcon />
          </IconButton>
          <IconButton color="error" onClick={() => handleDelete(item.id)}>
            <DeleteIcon />
          </IconButton>
        </>
      )
    },
  ];

  return (
    <div>
      <Button
        variant="contained"
        color="primary"
        startIcon={<AddIcon />}
        onClick={() => setDialogOpen(true)}
        sx={{ mb: 2 }}
      >
        Add History Item
      </Button>

      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              {columns.map((column) => (
                <TableCell key={column.id}>{column.label}</TableCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {items.map((item) => (
              <TableRow key={item.id}>
                {columns.map((column) => (
                  <TableCell key={column.id}>
                    {column.render ? column.render(item[column.id], item) : item[column.id]}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>

      <Dialog
        open={dialogOpen}
        onClose={handleDialogClose}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          {selectedItem ? 'Edit History Item' : 'Add History Item'}
        </DialogTitle>
        <DialogContent>
          <HistoryForm
            initialValues={selectedItem}
            onSuccess={handleFormSuccess}
            onCancel={handleDialogClose}
          />
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default HistoryList;
